validator:
function validate(input) {
  const [{ Activity = [] }] = input;
  const keys = new Set();
  for (const [player, device, date, games] of Activity) {
    if (player === null || date === null) return 'player_id and event_date are required.';
    if (device === null) return `Player ${player} needs a device_id on ${date}.`;
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) return `event_date ${date} is not YYYY-MM-DD.`;
    const key = `${player}|${date}`;
    if (keys.has(key)) return `Player ${player} has two rows on ${date}.`;
    keys.add(key);
    if (games !== null && games < 0) return 'games_played cannot be negative.';
  }
  return null;
}

generator:
function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const day = (y, m, d) => `${y}-${String(m).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
  const rows = size === 'small' ? pick(9) : 2000;
  const players = size === 'small' ? 4 : 400;
  const years = size === 'small' ? [2016, 2017] : [2015, 2016, 2017, 2018, 2019];
  const Activity = [], seen = new Set();
  for (let tries = 0; Activity.length < rows && tries < rows * 20; tries++) {
    const player = 1 + pick(players);
    const date = size === 'small' ? day(years[pick(2)], 1 + pick(3), 1 + pick(3)) : day(years[pick(years.length)], 1 + pick(12), 1 + pick(28));
    if (seen.has(`${player}|${date}`)) continue;
    seen.add(`${player}|${date}`);
    Activity.push([player, 1 + pick(5), date, pick(8)]);
  }
  return [{ Activity }];
}
